import json

booking_details = {
    "booking_time": "15 hours ago",
    "passengers": 2,
    "amount_paid": 1010
}

cancellation_policy = {
    "fee_per_passenger": 125
}

# Check the booking details against the policy
if booking_details["booking_time"] == "15 hours ago":
    fee = cancellation_policy["fee_per_passenger"] * booking_details["passengers"]
    refund = booking_details["amount_paid"] - fee
else:
    fee = refund = None

# Determine the decision
if fee is not None:
    decision = "cancel"
else:
    decision = "deny"

# Create the JSON response
response = {
    "reason": f"The policy is not applicable because the booking was made {booking_details['booking_time']}.",
    "decision": decision,
    "fee_per_passenger": fee if decision == "cancel" else None,
    "refund": refund if decision == "cancel" else None
}

print(json.dumps(response, indent=4))
